import{_ as i,o as t,c as l,aw as a}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"HTTP Status Codes","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/http/4-http-status-codes.md","filePath":"wiki/dev-commit/network/network/http/4-http-status-codes.md"}'),r={name:"wiki/dev-commit/network/network/http/4-http-status-codes.md"};function o(n,e,s,d,c,u){return t(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="http-status-codes" tabindex="-1">HTTP Status Codes <a class="header-anchor" href="#http-status-codes" aria-label="Permalink to &quot;HTTP Status Codes&quot;">​</a></h1><ul><li><strong>Коды состояния HTTP</strong> - код состояния является частью первой строки ответа сервера. Он представляет собой целое число из трёх цифр. Первая цифра указывает на класс состояния. За кодом ответа обычно следует отделённая пробелом поясняющая фраза на английском языке, которая разъясняет причину ответа</li></ul><h2 id="классы-кодов" tabindex="-1">Классы кодов <a class="header-anchor" href="#классы-кодов" aria-label="Permalink to &quot;Классы кодов&quot;">​</a></h2><ul><li>1xx - Информационный (informational). Информирование о процессе передачи</li><li>2xx - Успех (Success). Информирование о случаях успешного принятия и обработки запроса клиента</li><li>3xx - Перенаправление (Redirection). Сообщает клиенту, что для успешного выполнения операции необходимо сделать другой запрос, как правило, по другому URI</li><li>4xx - Ошибка клиента (Client Error)</li><li>5xx - Ошибка сервера (Server Error)</li></ul><h2 id="список-кодов" tabindex="-1">Список кодов <a class="header-anchor" href="#список-кодов" aria-label="Permalink to &quot;Список кодов&quot;">​</a></h2><h3 id="_1-information-100-199" tabindex="-1">1. Information [100 - 199] <a class="header-anchor" href="#_1-information-100-199" aria-label="Permalink to &quot;1. Information [100 - 199]&quot;">​</a></h3><ul><li>100 Continue - Сервер удовлетворён начальными сведениями о запросе, клиент может продолжать пересылать заголовки</li><li>101 Switching Protocols - Сервер выполняет требование клиента и переключает протоколы в соответствии с указанием, данным в поле заголовка Upgrade</li><li>102 Processing - Запрос принят, но на его обработку понадобится длительное время</li><li>103 Early Hints - Используется для раннего возврата части заголовков, когда заголовки полного ответа не могут быть быстро сформированы</li></ul><h3 id="_2-success-200-299" tabindex="-1">2. Success [200 - 299] <a class="header-anchor" href="#_2-success-200-299" aria-label="Permalink to &quot;2. Success [200 - 299]&quot;">​</a></h3><ul><li>200 Ok - Успешный запрос</li><li>201 Created - Создание нового ресурса</li><li>202 Accepted - Запрос был принят на обработку, но она не завершена</li><li>204 No Content - Сервер успешно обработал запрос, но в ответе были переданы только заголовки без тела сообщения</li><li>206 Partial Content - Сервер удачно выполнил частичный GET-запрос, возвратив только часть сообщения</li></ul><h3 id="_3-redirect-300-399" tabindex="-1">3. Redirect [300 - 399] <a class="header-anchor" href="#_3-redirect-300-399" aria-label="Permalink to &quot;3. Redirect [300 - 399]&quot;">​</a></h3><ul><li>300 Multiply Choices - По указанному URI существует несколько вариантов предоставления ресурса по типу MIME, по языку или по другим характеристикам</li><li>301 Moved Permanantly - Запрошенный документ был окончательно перенесен на новый URI, указанный в поле Location заголовка</li><li>304 Not Modified - Клиент запросил документ методом GET, использовал заголовок If-Modified-Since или If-None-Match и документ не изменился с указанного момента</li><li>305 Use Proxy - Запрос к запрашиваемому ресурсу должен осуществляться через прокси-сервер</li><li>307 Temporary Redirect - Запрашиваемый ресурс на короткое время доступен по другому URI, указанный в поле Location заголовка</li><li>308 Permanant Redirect - Запрашиваемый ресурс был окончательно перенесен на новый URI, указанный в поле Location заголовка</li></ul><h3 id="_4-client-error-400-499" tabindex="-1">4. Client Error [400 - 499] <a class="header-anchor" href="#_4-client-error-400-499" aria-label="Permalink to &quot;4. Client Error [400 - 499]&quot;">​</a></h3><ul><li>400 Bad Request - Сервер обнаружил в запросе клиента синтаксическую ошибку</li><li>401 Unauthorized - Для доступа к запрашиваемому ресурсу требуется аутентификация. В заголовке ответ должен содержать поле WWW-Authenticate с перечнем условий аутентификации</li><li>403 Forbidden - Клиент не уполномочен совершать операции с запрошенным ресурсом</li><li>404 Not Found - Сервер понял запрос, но не нашёл соответствующего ресурса по указанному URL</li><li>405 Method Not Allowed - Указанный клиентом метод нельзя применить к текущему ресурсу</li><li>406 Not Acceptable - Запрошенный URI не может удовлетворить переданным в заголовке характеристикам</li><li>407 Proxy Authentication Required - Для доступа к запрашиваемому ресурсу требуется аутентификация для прокси-сервера</li><li>408 Request Timeout - Истекло время ожидания сервером передачи от клиента</li><li>409 Conflict - Запрос не может быть выполнен из-за конфликтного обращения к ресурсу. Такое возможно, например, когда два клиента пытаются изменить ресурс с помощью метода PUT</li><li>410 Gone - Ресурс раньше был по указанному URL, но был удалён и теперь недоступен</li><li>411 Length Required - Для указанного ресурса клиент должен указать Content-Length в заголовке запроса</li><li>413 Payload To Large - Слишком большой размер тела запроса</li><li>414 URI Too Long - Слишком длинный URI</li></ul><h3 id="_5-server-error-500-599" tabindex="-1">5. Server Error [500 - 599] <a class="header-anchor" href="#_5-server-error-500-599" aria-label="Permalink to &quot;5. Server Error [500 - 599]&quot;">​</a></h3><ul><li>500 Internal Server Error - Любая внутренняя ошибка сервера, которая не входит в рамки остальных ошибок класса</li><li>501 Not Implemented - Сервер не поддерживает возможностей, необходимых для обработки запроса. Типичный ответ для случаев, когда сервер не понимает указанный в запросе метод</li><li>502 Bad Gateway - Сервер, выступая в роли шлюза или прокси-сервера, получил недействительное ответное сообщение от вышестоящего сервера</li><li>503 Service Unavailable - Сервер временно не имеет возможности обрабатывать запросы по техническим причинам (обслуживание, перегрузка и прочее)</li><li>504 Gateway Timeout - Сервер в роли шлюза или прокси-сервера не дождался ответа от вышестоящего сервера для завершения текущего запроса</li><li>522 Connection Timed Out - CDN не удалось подключиться к веб-серверу</li></ul>',15)])])}const _=i(r,[["render",o]]);export{m as __pageData,_ as default};
